CREATE TEMPORARY VIEW  aggr_sum_${grass_region_without_quote} AS
select item_id
    ,mapping_general
    ,sum(imp_cnt) imp_cnt
    ,sum(case when is_ads = 'false' then imp_cnt else 0 end) org_imp_cnt
    ,sum(click_cnt) click_cnt
    ,sum(case when is_ads = 'false' then click_cnt else 0 end) org_click_cnt
    ,sum(order_cnt) order_cnt
    ,sum(case when is_ads = 'false' then order_cnt else 0 end) org_order_cnt
    ,sum(gmv) gmv
    ,sum(case when is_ads = 'false' then gmv else 0 end) org_gmv
    ,sum(pc2_gmv) pc2_gmv
    ,sum(case when is_ads = 'false' then pc2_gmv else 0 end) org_pc2_gmv
from srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
where grass_region = ${grass_region}
and local_date = ${local_date}
and item_id>0
group by 1,2
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_raw_step1_${grass_region_without_quote} as
select
    item_id
     ,ads_revenue_usd
     ,case   when T2.traffic_type = 'Livestream' then 'Live Streaming'
             when T1.entrance = 23 then 'Image Search'
             else coalesce(T2.traffic_type, 'Other') END
        as common_feature
from
    (
        select
            item_id
             ,expenditure_amt_usd as ads_revenue_usd
             ,entrance
        from mp_paidads.dwd_advertise_performance_di__reg_s0_live
        where grass_region in (${grass_region}) and grass_date=${local_date} and tz_type='local'
        and item_id>0
    ) as T1
        left join (
        select
            entrance
             ,max(traffic_type) as traffic_type
        from mp_paidads.dim_entry_point_mapping_v2
        group by 1
    ) as T2 on T1.entrance = T2.entrance
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_raw_step2_${grass_region_without_quote} AS
select
    item_id
     ,common_feature
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step1_${grass_region_without_quote}
group by
    item_id
       ,common_feature
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_${grass_region_without_quote} as
select
    item_id
     ,common_feature
     ,ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('Search','You May Also Like','Daily Discover','Post Purchase','Shop','Live Streaming','Video')
union all
select
    item_id
     ,'S&R__ALL__' as common_feature
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('Search','Image Search','You May Also Like','Daily Discover','Post Purchase')
group by
    item_id
union all
select
    item_id
     ,'__ALL__' as common_feature
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
group by
    item_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_item_aggr_1d partition (grass_region = ${grass_region},local_date = ${local_date})
select coalesce(a.item_id,b.item_id) item_id
     ,coalesce(mapping_general,common_feature) mapping_general
     ,coalesce(imp_cnt,0) imp_cnt
     ,coalesce(org_imp_cnt,0) org_imp_cnt
     ,coalesce(click_cnt,0) click_cnt
     ,coalesce(org_click_cnt,0) org_click_cnt
     ,coalesce(order_cnt,0) order_cnt
     ,coalesce(org_order_cnt,0) org_order_cnt
     ,coalesce(gmv,0) gmv
     ,coalesce(org_gmv,0) org_gmv
     ,coalesce(pc2_gmv,0) pc2_gmv
     ,coalesce(org_pc2_gmv,0) org_pc2_gmv
     ,ads_revenue_usd
from aggr_sum_${grass_region_without_quote} a
full outer join ads_${grass_region_without_quote} b
on a.item_id = b.item_id
and a.mapping_general = b.common_feature
;
